#!/usr/bin/env python3
"""Export eval_summary.json to LaTeX table fragments for 2-Dissertation-Draft."""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

from common import ROOT, load_config, load_json  # noqa: E402

LATEX_HEADER = r"""% DUMMY DATA — Replace after running:
%   A-Skill-Programs/margin_rank/scripts/run_dissertation_eval.py --fixtures --n-wallets 571
% Real data: BigQuery goog_blockchain_arbitrum_one_us + GMX EventEmitter logs
% Generated by export_latex_results.py — do not edit by hand unless re-export fails
"""


def _fmt(v: float | None, digits: int = 3) -> str:
    if v is None:
        return "---"
    return f"{v:.{digits}f}"


def write_benchmark_table(summary: dict, out: Path) -> None:
    b = summary["benchmark"]
    er = b["endorserank"]
    awp = b["awp"]
    n = summary.get("n_wallets", b.get("n_wallets", "---"))
    body = f"""{LATEX_HEADER}
\\begin{{table}}[htbp]
\\centering
\\caption{{Computational benchmark on matched wallet sample ($n={n}$).}}
\\label{{tab:benchmark-runtime}}
\\begin{{tabular}}{{lrrrr}}
\\toprule
Method & Runtime (s) & Peak memory (MB) & Iterations & Edge count \\\\
\\midrule
EndorseRank & {_fmt(er['runtime_sec_mean'])} & {_fmt(er['peak_memory_mb'], 1)} & {_fmt(er['iterations_mean'], 1)} & {er['edge_count']} \\\\
AWP & {_fmt(awp['runtime_sec_mean'])} & {_fmt(awp['peak_memory_mb'], 1)} & {_fmt(awp['iterations_mean'], 1)} & {awp['edge_count']} \\\\
\\bottomrule
\\end{{tabular}}
\\end{{table}}
"""
    out.write_text(body, encoding="utf-8")


def _alignment_rows(method: dict, proxies: tuple[str, ...], labels: dict[str, str]) -> str:
    lines = []
    for p in proxies:
        if p not in method:
            continue
        row = method[p]
        lines.append(
            f"{labels.get(p, p)} & {_fmt(row.get('spearman_rho'))} & {_fmt(row.get('kendall_tau'))} \\\\"
        )
    return "\n".join(lines)


def write_transfer_alignment(summary: dict, out: Path) -> None:
    a = summary["alignment"]
    labels = {"in_degree": "In-degree", "in_value": "In-value (sum inbound)"}
    body = f"""{LATEX_HEADER}
\\begin{{table}}[htbp]
\\centering
\\caption{{Domain alignment with transfer proxies (Do et al.\\ 2023 baseline). Kendall $\\tau$ and Spearman $\\rho$ between reputation scores and proxy rankings.}}
\\label{{tab:alignment-transfer}}
\\begin{{tabular}}{{lcc}}
\\toprule
Proxy & Spearman $\\rho$ & Kendall $\\tau$ \\\\
\\midrule
\\multicolumn{{3}}{{l}}{{\\textit{{EndorseRank}}}} \\\\
{_alignment_rows(a['endorserank'], ('in_degree', 'in_value'), labels)}
\\addlinespace
\\multicolumn{{3}}{{l}}{{\\textit{{AWP}}}} \\\\
{_alignment_rows(a['awp'], ('in_degree', 'in_value'), labels)}
\\bottomrule
\\end{{tabular}}
\\end{{table}}
"""
    out.write_text(body, encoding="utf-8")


def write_gmx_alignment(summary: dict, out: Path) -> None:
    a = summary["alignment"]
    labels = {
        "close_success_count": "Close-success count",
        "realized_gain_proxy": "Realized gain proxy",
        "close_success_rate": "Close success rate",
    }
    body = f"""{LATEX_HEADER}
\\begin{{table}}[htbp]
\\centering
\\caption{{Domain alignment with GMX V2 margin-trading success proxies on Arbitrum One.}}
\\label{{tab:alignment-gmx}}
\\begin{{tabular}}{{lcc}}
\\toprule
Proxy & Spearman $\\rho$ & Kendall $\\tau$ \\\\
\\midrule
\\multicolumn{{3}}{{l}}{{\\textit{{EndorseRank}}}} \\\\
{_alignment_rows(a['endorserank'], ('close_success_count', 'realized_gain_proxy', 'close_success_rate'), labels)}
\\addlinespace
\\multicolumn{{3}}{{l}}{{\\textit{{AWP}}}} \\\\
{_alignment_rows(a['awp'], ('close_success_count', 'realized_gain_proxy', 'close_success_rate'), labels)}
\\bottomrule
\\end{{tabular}}
\\end{{table}}
"""
    out.write_text(body, encoding="utf-8")


def write_summary_table(summary: dict, out: Path) -> None:
    a = summary["alignment"]
    er_x = a["endorserank_cross_proxy"]
    awp_x = a["awp_cross_proxy"]
    body = f"""{LATEX_HEADER}
\\begin{{table}}[htbp]
\\centering
\\caption{{Cross-proxy mean Kendall $\\tau$: transfer family vs.\\ GMX margin family (Claim~3--4 summary).}}
\\label{{tab:alignment-summary}}
\\begin{{tabular}}{{lcc}}
\\toprule
Method & Transfer proxies (mean $\\tau$) & GMX proxies (mean $\\tau$) \\\\
\\midrule
EndorseRank & {_fmt(er_x.get('transfer_family_mean_tau'))} & {_fmt(er_x.get('gmx_family_mean_tau'))} \\\\
AWP & {_fmt(awp_x.get('transfer_family_mean_tau'))} & {_fmt(awp_x.get('gmx_family_mean_tau'))} \\\\
\\bottomrule
\\end{{tabular}}
\\end{{table}}
"""
    out.write_text(body, encoding="utf-8")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--summary", type=Path, help="eval_summary.json path")
    parser.add_argument(
        "--out-dir",
        type=Path,
        help="LaTeX tables output directory",
    )
    args = parser.parse_args()

    config = load_config()
    summary_path = args.summary or Path(config["paths"]["eval_summary"])
    if not summary_path.exists():
        print(f"Missing {summary_path}; run run_dissertation_eval.py first.")
        return 1

    repo_root = ROOT.parents[1]
    out_dir = args.out_dir or (repo_root / "2-Dissertation-Draft" / "results" / "tables")
    out_dir.mkdir(parents=True, exist_ok=True)

    summary = load_json(summary_path)
    write_benchmark_table(summary, out_dir / "benchmark-runtime.tex")
    write_transfer_alignment(summary, out_dir / "alignment-transfer.tex")
    write_gmx_alignment(summary, out_dir / "alignment-gmx.tex")
    write_summary_table(summary, out_dir / "alignment-summary.tex")

    print(f"LaTeX tables -> {out_dir}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
